def load_cards():
    return [
        {"id": "c1", "score": 0.9},
        {"id": "c2", "score": 0.4},
    ]

def validate_cards(cards):
    return [card["id"] for card in cards if card["score"] < 0.5]

def print_report(errors):
    return len(errors)

cards = load_cards()
errors = validate_cards(cards)
report_count = print_report(errors)
approved = not errors
print(errors, report_count, approved)
